/* @lc app=leetcode id=2476 lang=kotlin */ class Solution { fun closestNodes(root: TreeNode?, queries: List<Int>): List<List<Int>> = generateSequence(listOf(root!!)) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.flatten().map { it.`val` }.sorted().toList().let { a -> queries.map { q -> a.binarySearch(q).let { i -> if (i >= 0) listOf(q, q) else (-i - 1).let { ins -> listOf(a.getOrNull(ins - 1) ?: -1, a.getOrNull(ins) ?: -1) } } } } }